public Set getAllowedValues()
{
    InventTableModule   inventTableModule;
    var ret = new Set(Types::Real);

    while select RetailInventoryAvailabilityBuffer from inventTableModule
        group by RetailInventoryAvailabilityBuffer
    {
        if (!ret.in(inventTableModule.RetailInventoryAvailabilityBuffer))
        {
            ret.add(inventTableModule.RetailInventoryAvailabilityBuffer);
        }
    }

    return ret;
}

